   321  #define HB_TAG_sfnt HB_TAG ('s','f','n','t')
   322
   323  struct ResourceTypeRecord
   324  {
   325    inline unsigned int get_resource_count (void) const
   326    { return tag == HB_TAG_sfnt ? resCountM1 + 1 : 0; }
   327
   328    inline bool is_sfnt (void) const { return tag == HB_TAG_sfnt; }
   329
   330    inline const ResourceRecord& get_resource_record (unsigned int i,
   475      case TrueTypeTag:   return 1;
   476      case TTCTag:        return u.ttcHeader.get_face_count ();
   477      case DFontTag:      return u.rfHeader.get_face_count ();
   478      default:            return 0;
   479      }
   480    }
   481    inline const OpenTypeFontFace& get_face (unsigned int i, unsigned int *base_offset = nullptr) const
   482    {
   483      if (base_offset)
   484        *base_offset = 0;
   485      switch (u.tag) {
   486      /* Note: for non-collection SFNT data we ignore index.  This is because
   487       * Apple dfont container is a container of SFNT's.  So each SFNT is a
   488       * non-TTC, but the index is more than zero. */
   489      case CFFTag:        /* All the non-collection tags */
   490      case TrueTag:
   491      case Typ1Tag:
   492      case TrueTypeTag:   return u.fontFace;
   493      case TTCTag:        return u.ttcHeader.get_face (i);
   494      case DFontTag:      return u.rfHeader.get_face (i, base_offset);
   495      default:            return Null(OpenTypeFontFace);
   496      }
   497    }
   498
   499    inline bool serialize_single (hb_serialize_context_t *c,
   500                                  hb_tag_t sfnt_tag,
   501                                  Supplier<hb_tag_t> &tags,
   502                                  Supplier<hb_blob_t *> &blobs,
   503                                  unsigned int table_count)
   504    {
   505      TRACE_SERIALIZE (this);
   506      assert (sfnt_tag != TTCTag);
   507      if (unlikely (!c->extend_min (*this))) return_trace (false);
   508      return_trace (u.fontFace.serialize (c, sfnt_tag, tags, blobs, table_count));
   509    }
   510
   511    inline bool sanitize (hb_sanitize_context_t *c) const
   512    {
   513      TRACE_SANITIZE (this);
   514      if (unlikely (!u.tag.sanitize (c))) return_trace (false);
   515      switch (u.tag) {
   516      case CFFTag:        /* All the non-collection tags */
   517      case TrueTag:
   518      case Typ1Tag:
   519      case TrueTypeTag:   return_trace (u.fontFace.sanitize (c));
   520      case TTCTag:        return_trace (u.ttcHeader.sanitize (c));
   521      case DFontTag:      return_trace (u.rfHeader.sanitize (c));
   522      default:            return_trace (true);
   523      }
   524    }
   525
   526    protected:
   527    union {
   528    Tag                   tag;            /* 4-byte identifier. */
   529    OpenTypeFontFace      fontFace;
   530    TTCHeader             ttcHeader;
   531    ResourceForkHeader    rfHeader;
   532    } u;
   533    public:
   534    DEFINE_SIZE_UNION (4, tag);
   535  };
